/** User-visible strings emitted by the Placehold TinyMCE plugin. */
export interface PlaceholdStrings {
  placeholdToolbarText: string;
  placeholdToolbarTooltip: string;
  placeholdMenuText: string;
  placeholdDialogTitle: string;
  placeholdWidthLabel: string;
  placeholdHeightLabel: string;
  placeholdBackgroundColorLabel: string;
  placeholdTextColorLabel: string;
  placeholdTextLabel: string;
  placeholdAltTextLabel: string;
  placeholdInsertButton: string;
  placeholdCancelButton: string;
  placeholdInvalidDimensions: string;
  placeholdInvalidColor: string;
  placeholdAltFallback: string;
}

/** English defaults for the Placehold TinyMCE interface. */
export const PLACEHOLD_STRINGS: PlaceholdStrings = Object.fromEntries(
  Object.entries(englishBase)
    .filter(([key]) => key !== "$schema")
    .map(([key, value]) => [key, typeof value === "string" ? value : value.message]),
) as unknown as PlaceholdStrings;

/** Fill a localized string's `{{name}}` placeholders with runtime values. */
export function formatPlaceholdString(
  template: string,
  values: Readonly<Record<string, string | number>>,
): string {
  return template.replace(/\{\{(\w+)\}\}/gu, (_match, key: string) => String(values[key] ?? ""));
}
"}

{"filePath":"/Users/dwahl/Scripts/pantoken/plugins/tinymce/placehold/README.md","content":"# @pantoken/tinymce-placehold

A TinyMCE 5 plugin for inserting PNG placeholder images from [placehold.co](https://placehold.co/).

## Usage

```ts
import tinymce from "tinymce";
import {
  createPlaceholdPlugin,
  PLACEHOLD_PLUGIN_NAME,
  PLACEHOLD_TOOLBAR_NAME,
} from "@pantoken/tinymce-placehold";

tinymce.PluginManager.add(PLACEHOLD_PLUGIN_NAME, createPlaceholdPlugin());

tinymce.init({
  selector: "#editor",
  plugins: PLACEHOLD_PLUGIN_NAME,
  toolbar: PLACEHOLD_TOOLBAR_NAME,
});
```

The dialog accepts width, height, background color, text color, custom image text, and alt text. It defaults to a 600 by 400 image with `#eeeeee` and `#31343c`. Placehold supports dimensions from 10 through 4000 pixels. This plugin always emits an explicit `.png` URL.

When alt text is blank, the plugin uses the custom image text or a localized dimension-based fallback. Author-entered image text and alt text are never translated. All plugin-owned interface strings participate in pantoken's `tinymce.strings` localization pipeline.

Use `onInsert` to react after an image is inserted:

```ts
createPlaceholdPlugin({
  defaults: { width: 800, height: 450 },
  onInsert(image) {
    console.log(image.url);
  },
});
```

Rendered placeholders require network access to `https://placehold.co`.
"}

{"filePath":"/Users/dwahl/Scripts/pantoken/plugins/tinymce/placehold/src/index.ts","content":"import type { Editor } from "tinymce";
import {
  formatPlaceholdString,
  PLACEHOLD_STRINGS,
  type PlaceholdStrings,
} from "./strings.js";

/** The plugin name used in TinyMCE's `plugins` option. */
export const PLACEHOLD_PLUGIN_NAME = "placehold";
/** The control name used in TinyMCE's `toolbar` option. */
export const PLACEHOLD_TOOLBAR_NAME = "placehold";
/** The command that opens the placeholder image dialog. */
export const PLACEHOLD_COMMAND = "pantokenOpenPlacehold";

/** Author-controlled values used to build a placeholder image. */
export interface PlaceholdImageInput {
  width: number | string;
  height: number | string;
  backgroundColor: string;
  textColor: string;
  text?: string;
  altText?: string;
}

/** Validated placeholder image data passed to TinyMCE and consumers. */
export interface PlaceholdImage {
  width: number;
  height: number;
  backgroundColor: string;
  textColor: string;
  text: string;
  altText: string;
  url: string;
}

/** Configuration for {@link createPlaceholdPlugin}. */
export interface PlaceholdPluginOptions {
  /** Initial values shown when the dialog opens. */
  defaults?: Partial<PlaceholdImageInput>;
  /** Resolved interface strings, typically generated from the `tinymce.strings` catalog. */
  strings?: Partial<PlaceholdStrings>;
  /** Called after the generated image has been inserted. */
  onInsert?: (image: PlaceholdImage) => void;
}

const DEFAULT_INPUT: PlaceholdImageInput = {
  width: 600,
  height: 400,
  backgroundColor: "#eeeeee",
  textColor: "#31343c",
  text: "",
  altText: "",
};
const DIMENSION_MIN = 10;
const DIMENSION_MAX = 4000;
const HEX_COLOR = /^#?(?:[\da-f]{3}|[\da-f]{6})$/iu;

function parseDimension(value: number | string): number {
  const dimension = typeof value === "number" ? value : Number(value);
  if (!Number.isInteger(dimension) || dimension < DIMENSION_MIN || dimension > DIMENSION_MAX) {
    throw new RangeError("invalid-dimensions");
  }
  return dimension;
}

function normalizeColor(value: string): string {
  if (!HEX_COLOR.test(value)) throw new TypeError("invalid-color");
  return value.replace(/^#/u, "").toUpperCase();
}

/** Validate image input and build its explicit placehold.co PNG URL. */
export function buildPlaceholdImage(
  input: PlaceholdImageInput,
  strings: PlaceholdStrings = PLACEHOLD_STRINGS,
): PlaceholdImage {
  const width = parseDimension(input.width);
  const height = parseDimension(input.height);
  const backgroundColor = normalizeColor(input.backgroundColor);
  const textColor = normalizeColor(input.textColor);
  const text = input.text ?? "";
  const requestedAltText = input.altText ?? "";
  const altText =
    requestedAltText ||
    text ||
    formatPlaceholdString(strings.placeholdAltFallback, {
      width,
      height,
    });
  const url = new URL(
    `https://placehold.co/${width}x${height}/${backgroundColor}/${textColor}.png`,
  );
  if (text) url.searchParams.set("text", text);

  return {
    width,
    height,
    backgroundColor,
    textColor,
    text,
    altText,
    url: url.toString(),
  };
}

/** Build the TinyMCE plugin callback for the Placehold image interface. */
export function createPlaceholdPlugin(options: PlaceholdPluginOptions = {}) {
  return function pantokenPlaceholdPlugin(editor: Editor) {
    const strings: PlaceholdStrings = { ...PLACEHOLD_STRINGS, ...options.strings };
    const defaults = { ...DEFAULT_INPUT, ...options.defaults };
    const openDialog = (): void => {
      editor.windowManager.open({
        title: strings.placeholdDialogTitle,
        body: {
          type: "panel",
          items: [
            { type: "input", name: "width", label: strings.placeholdWidthLabel },
            { type: "input", name: "height", label: strings.placeholdHeightLabel },
            {
              type: "colorinput",
              name: "backgroundColor",
              label: strings.placeholdBackgroundColorLabel,
            },
            { type: "colorinput", name: "textColor", label: strings.placeholdTextColorLabel },
            { type: "input", name: "text", label: strings.placeholdTextLabel },
            { type: "input", name: "altText", label: strings.placeholdAltTextLabel },
          ],
        },
        initialData: {
          width: String(defaults.width),
          height: String(defaults.height),
          backgroundColor: defaults.backgroundColor,
          textColor: defaults.textColor,
          text: defaults.text ?? "",
          altText: defaults.altText ?? "",
        },
        buttons: [
          { type: "cancel", text: strings.placeholdCancelButton },
          { type: "submit", text: strings.placeholdInsertButton, primary: true },
        ],
        onSubmit: (api): void => {
          try {
            const image = buildPlaceholdImage(api.getData() as unknown as PlaceholdImageInput, strings);
            const html = editor.dom.createHTML("img", {
              src: image.url,
              alt: image.altText,
              width: String(image.width),
              height: String(image.height),
            });
            editor.insertContent(html);
            api.close();
            options.onInsert?.(image);
          } catch (error) {
            editor.windowManager.alert(
              error instanceof RangeError
                ? strings.placeholdInvalidDimensions
                : strings.placeholdInvalidColor,
            );
          }
        },
      });
    };

    editor.addCommand(PLACEHOLD_COMMAND, openDialog);
    editor.ui.registry.addButton(PLACEHOLD_TOOLBAR_NAME, {
      icon: "add-file",
      tooltip: strings.placeholdToolbarTooltip,
      onAction: openDialog,
    });
    editor.ui.registry.addMenuItem(PLACEHOLD_TOOLBAR_NAME, {
      text: strings.placeholdMenuText,
      icon: "add-file",
      onAction: openDialog,
    });

    return {};
  };
}

export { PLACEHOLD_STRINGS, type PlaceholdStrings } from "./strings.js";
"}

{"filePath":"/Users/dwahl/Scripts/pantoken/plugins/tinymce/placehold/tests/index.test.ts","content":"import { describe, expect, test, vi } from "vite-plus/test";
import {
  buildPlaceholdImage,
  createPlaceholdPlugin,
  PLACEHOLD_COMMAND,
  PLACEHOLD_PLUGIN_NAME,
  PLACEHOLD_TOOLBAR_NAME,
} from "../src/index.ts";

function fakeEditor() {
  const registry = { addButton: vi.fn(), addMenuItem: vi.fn() };
  return {
    addCommand: vi.fn(),
    dom: { createHTML: vi.fn(() => '<img src="safe">') },
    insertContent: vi.fn(),
    ui: { registry },
    windowManager: { alert: vi.fn(), open: vi.fn() },
  };
}

describe("buildPlaceholdImage", () => {
  test("builds an explicit PNG URL and dimension alt fallback", () => {
    expect(
      buildPlaceholdImage({
        width: 600,
        height: "400",
        backgroundColor: "#eee",
        textColor: "31343c",
      }),
    ).toEqual({
      width: 600,
      height: 400,
      backgroundColor: "EEE",
      textColor: "31343C",
      text: "",
      altText: "600 by 400 placeholder image",
      url: "https://placehold.co/600x400/EEE/31343C.png",
    });
  });

  test("encodes custom text without changing its value and uses it as the alt fallback", () => {
    const image = buildPlaceholdImage({
      width: 800,
      height: 450,
      backgroundColor: "abcdef",
      textColor: "123",
      text: "Hello & goodbye",
    });
    expect(image.text).toBe("Hello & goodbye");
    expect(image.altText).toBe("Hello & goodbye");
    expect(image.url).toBe("https://placehold.co/800x450/ABCDEF/123.png?text=Hello+%26+goodbye");
  });

  test.each([9, 4001, 12.5, "wide"])("rejects invalid dimension %s", (width) => {
    expect(() =>
      buildPlaceholdImage({
        width,
        height: 400,
        backgroundColor: "eee",
        textColor: "333",
      }),
    ).toThrow(RangeError);
  });

  test("rejects invalid colors", () => {
    expect(() =>
      buildPlaceholdImage({
        width: 600,
        height: 400,
        backgroundColor: "transparent",
        textColor: "333",
      }),
    ).toThrow(TypeError);
  });
});

describe("createPlaceholdPlugin", () => {
  test("exports stable TinyMCE names and registers the add-file interface", () => {
    expect(PLACEHOLD_PLUGIN_NAME).toBe("placehold");
    expect(PLACEHOLD_TOOLBAR_NAME).toBe("placehold");
    const editor = fakeEditor();
    createPlaceholdPlugin()(editor as never);

    expect(editor.addCommand).toHaveBeenCalledWith(PLACEHOLD_COMMAND, expect.any(Function));
    expect(editor.ui.registry.addButton).toHaveBeenCalledWith(
      PLACEHOLD_TOOLBAR_NAME,
      expect.objectContaining({ icon: "add-file", tooltip: "Insert a placeholder image" }),
    );
    expect(editor.ui.registry.addMenuItem).toHaveBeenCalledWith(
      PLACEHOLD_TOOLBAR_NAME,
      expect.objectContaining({ icon: "add-file", text: "Placeholder image…" }),
    );
  });

  test("opens localized controls and safely inserts the submitted image", () => {
    const editor = fakeEditor();
    const onInsert = vi.fn();
    createPlaceholdPlugin({
      strings: { placeholdDialogTitle: "Localized title" },
      onInsert,
    })(editor as never);

    const open = editor.ui.registry.addButton.mock.calls[0]?.[1].onAction as () => void;
    open();
    const dialog = editor.windowManager.open.mock.calls[0]?.[0];
    expect(dialog.title).toBe("Localized title");
    expect(dialog.initialData).toMatchObject({ width: "600", height: "400" });

    const api = {
      close: vi.fn(),
      getData: () => ({
        width: "640",
        height: "360",
        backgroundColor: "#abcdef",
        textColor: "#123",
        text: "Author <text>",
        altText: "Author & alt",
      }),
    };
    dialog.onSubmit(api);

    expect(editor.dom.createHTML).toHaveBeenCalledWith("img", {
      src: "https://placehold.co/640x360/ABCDEF/123.png?text=Author+%3Ctext%3E",
      alt: "Author & alt",
      width: "640",
      height: "360",
    });
    expect(editor.insertContent).toHaveBeenCalledWith('<img src="safe">');
    expect(api.close).toHaveBeenCalled();
    expect(onInsert).toHaveBeenCalledWith(
      expect.objectContaining({ text: "Author <text>", altText: "Author & alt" }),
    );
  });

  test("keeps the dialog open and reports localized validation errors", () => {
    const editor = fakeEditor();
    createPlaceholdPlugin({ strings: { placeholdInvalidDimensions: "Localized dimensions" } })(
      editor as never,
    );
    const open = editor.ui.registry.addButton.mock.calls[0]?.[1].onAction as () => void;
    open();
    const dialog = editor.windowManager.open.mock.calls[0]?.[0];
    const api = {
      close: vi.fn(),
      getData: () => ({
        width: "2",
        height: "400",
        backgroundColor: "eee",
        textColor: "333",
      }),
    };

    dialog.onSubmit(api);

    expect(editor.windowManager.alert).toHaveBeenCalledWith("Localized dimensions");
    expect(api.close).not.toHaveBeenCalled();
    expect(editor.insertContent).not.toHaveBeenCalled();
  });
});
